// Vocal Drive / Edge: Suno Studio audio effect (applied to rendered audio, not a lyric tag).
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Pre-emphasis: g.biquad highshelf near 3kHz driven by 'edge' dB to lift highs before saturation.
//   3. Drive: scale by 'drive' (dB via g.dbToLin) into two saturators.
//   4. Soft-to-hard blend: soft = g.tanh(driven); hard = g.tanh(clamp(driven, -0.7, 0.7) scaled to be harsher).
//      g.lerp on 'hardness' (0..1) blends soft toward hard.
//   5. Dry/wet: g.lerp between trimmed dry and the saturated signal by 'dry/wet mix'.
//   6. Output gain, bypass select via g.lerp, then g.tanh safety before g.output.
// Bypass: g.lerp(bypass, out, trimmed) ASSUMES the 'bypass' enum resolves to 0 ('off') / 1 ('on'), so
// 'off' passes the PROCESSED signal and 'on' passes the DRY signal (see AUTHORING.md).
// ASSUMPTION: the highshelf g.biquad stage passes a 'gainDb' field not confirmed from the one example (see AUTHORING.md).
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var edgeDb = g.input('edge');
  var driveDb = g.input('drive');
  var hardnessPct = g.input('hardness');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var driveLin = g.dbToLin(driveDb);
  var hardness = g.clamp(g.div(hardnessPct, g.constant(100)), g.zero(), g.constant(1));
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var emphasized = g.biquad({ input: trimmed, cutoff: g.constant(3000), resonance: g.constant(0.707), mode: 'highshelf', gainDb: edgeDb });
    var driven = g.mul(emphasized, driveLin);
    var soft = g.tanh(driven);
    // harder curve: push harder into tanh then clamp the extremes for a squarer edge.
    var hard = g.clamp(g.tanh(g.mul(driven, g.constant(2))), g.constant(-0.95), g.constant(0.95));
    var sat = g.lerp(hardness, soft, hard);
    var wet = g.lerp(mix, trimmed, sat);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
